const item = $input.first();
return [{
  json: {
    ...item.json,
    ntfyTopic: 'isc-manager',
    ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
    iscManagerBotUrl: 'http://isc-manager-bot.isc-manager-bot.svc.cluster.local:8080',
    startNummer: '',
    fenster: 10,
    mailAn: 'peter.kretzer@dlrg.org',
    mailVon: 'n8n@pkr-service.de'
  }
}];

const cfg = $input.first().json;
const form = cfg['Letzte bekannte Mitgliedsnummer'];
if (form !== undefined) {
  const after = String(form).trim();
  const rawWindow = cfg['Fenster (1 bis 25)'];
  const fenster = rawWindow === undefined || rawWindow === null || rawWindow === '' ? cfg.fenster : Number(rawWindow);
  if (!/^\d{13}$/.test(after)) {
    return [{ json: { ...cfg, bereit: false, fehlertext: 'Testformular: Mitgliedsnummer muss 13 Ziffern haben' } }];
  }
  if (!Number.isInteger(fenster) || fenster < 1 || fenster > 25) {
    return [{ json: { ...cfg, bereit: false, fehlertext: 'Testformular: Fenster muss eine ganze Zahl von 1 bis 25 sein' } }];
  }
  return [{ json: { ...cfg, bereit: true, test: true, mailSenden: cfg['Mail an Empfaenger senden'] === 'Ja', after, payload: { after, window: fenster } } }];
}
const store = $getWorkflowStaticData('global');
const known = /^\d{13}$/.test(store.letzteNummer || '') ? store.letzteNummer : '';
const start = /^\d{13}$/.test(cfg.startNummer || '') ? cfg.startNummer : '';
const after = known || start;
if (after === '') {
  return [{ json: { ...cfg, bereit: false, fehlertext: 'Keine Startnummer: in Node Konfiguration die zuletzt bekannte Mitgliedsnummer (13 Ziffern) als startNummer eintragen' } }];
}
return [{ json: { ...cfg, bereit: true, test: false, mailSenden: true, after, payload: { after, window: cfg.fenster } } }];

const res = $input.first().json;
const stand = $('Stand lesen').first().json;
const test = stand.test === true;
const mailSenden = stand.mailSenden === true;
const members = Array.isArray(res.members) ? res.members : [];
const zeilen = members.map((m) => m.number + ' ' + m.name + (m.active ? '' : ' (nicht aktiv)'));
if (test) {
  const kopf = members.length === 0 ? 'Keine hoehere Nummer gefunden' : members.length + ' neue Nummer(n) gefunden';
  const fuss = 'Geprueft: ' + res.checked + ' Nummern ab ' + res.after + ', hoechste: ' + res.highest;
  const probes = Array.isArray(res.probes) ? res.probes : [];
  const treffer = probes.length > 0 ? 'Treffer je Nummer: ' + probes.map((p) => String(p.number).slice(-6) + '=' + p.hits + (p.hits > 0 && !(p.seen || []).includes(p.number) ? ' (gesehen: ' + (p.seen || []).map((s) => String(s).slice(-6)).join('/') + ')' : '')).join(', ') : '';
  return [{ json: { neu: true, test, mailSenden, members, titel: 'Test: Neue Mitglieder in SEWOBE', text: [kopf, ...zeilen, fuss, treffer].filter(Boolean).join('\n') } }];
}
const store = $getWorkflowStaticData('global');
if (/^\d{13}$/.test(res.highest || '')) store.letzteNummer = res.highest;
if (members.length === 0) {
  return [{ json: { neu: false } }];
}
const titel = members.length === 1 ? 'Neues Mitglied in SEWOBE' : members.length + ' neue Mitglieder in SEWOBE';
return [{ json: { neu: true, test, mailSenden, members, titel, text: zeilen.join('\n') } }];

const cfg = $('Konfiguration').first().json;
const res = $input.first().json;
if (res.mailSenden !== true) return [];
const gefunden = Array.isArray(res.members) ? res.members : [];
const members = gefunden.length > 0 ? gefunden : (res.test ? [{ number: '1002011000000', name: 'Beispiel, Person', active: true }] : []);
if (members.length === 0) return [];
const html = (wert) => String(wert ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const anzeige = (name) => {
  const teile = String(name || '').split(',').map((t) => t.trim()).filter(Boolean);
  if (teile.length !== 2) return teile[0] || '-';
  const zusatz = (teile[1].match(/\([^)]*\)/) || [''])[0];
  const vorname = teile[1].replace(/\([^)]*\)/, '').replace(/\s+/g, ' ').trim();
  return (vorname + ' ' + teile[0] + (zusatz ? ' ' + zusatz : '')).trim();
};
const quelle = 'ISC-Manager-Bot';
const thema = cfg.ntfyTopic;
const titel = (res.test ? 'Test: ' : '') + (members.length === 1 ? 'Neues Mitglied in SEWOBE' : members.length + ' neue Mitglieder in SEWOBE');
const zeit = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'medium' });
const zeilen = members.map((m) => '<tr><td style="padding:4px 24px 4px 0">' + html(anzeige(m.name)) + '</td><td style="padding:4px 0">' + html(m.number) + '</td></tr>').join('');
const inhalt = '<table style="font-size:14px;line-height:1.5;border-collapse:collapse"><tr style="text-align:left"><th style="padding:4px 24px 4px 0">Name</th><th style="padding:4px 0">Mitgliedsnummer</th></tr>' + zeilen + '</table>';
const mailHtml = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px">'
  + '<div style="background:#1565c0;color:#ffffff;padding:12px 16px;border-radius:6px 6px 0 0;font-size:16px"><b>ℹ️ Info</b> – ' + html(titel) + '</div>'
  + '<div style="border:1px solid #dddddd;border-top:none;padding:16px;border-radius:0 0 6px 6px">'
  + '<div style="margin:0 0 16px">' + inhalt + '</div>'
  + '<table style="font-size:12px;color:#666666;border-collapse:collapse">'
  + '<tr><td style="padding:2px 12px 2px 0">Quelle</td><td>' + html(quelle) + '</td></tr>'
  + '<tr><td style="padding:2px 12px 2px 0">Zeit</td><td>' + html(zeit) + '</td></tr>'
  + '<tr><td style="padding:2px 12px 2px 0">ntfy-Thema</td><td>' + html(thema) + '</td></tr>'
  + '</table></div></div>';
const text = titel + '\n\n' + members.map((m) => anzeige(m.name) + ' - ' + m.number).join('\n') + '\n\nQuelle: ' + quelle + '\nZeit: ' + zeit;
const betreff = ('[Info] ' + quelle + ': ' + titel).replace(/[\r\n]+/g, ' ').slice(0, 200);
return [{ json: { mailAn: cfg.mailAn, mailVon: cfg.mailVon, betreff, text, html: mailHtml } }];
